<x-layouts.wiki :title="'편성 분석'">
    <section class="mx-auto max-w-[1600px] px-4 py-5 lg:px-8" x-data="formation(@js($members), @js($songs), @js($snapshots))">
        <div class="grid gap-5 lg:grid-cols-[minmax(0,1fr)_360px]">
            <div>
                <div class="grid grid-cols-2 gap-3 sm:grid-cols-5">
                    <template x-for="(slot,index) in slots" :key="index">
                        <button @click="openSlot(index)" class="relative aspect-[3/4] overflow-hidden rounded-lg border bg-white text-left" :class="active===index?'border-[#6c5ce7] ring-2 ring-[#6c5ce7]/20':'border-slate-200'">
                            <template x-if="slot"><div class="h-full"><img :src="slot.image_url" class="h-full w-full object-cover"><div class="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/95 to-transparent p-3 pt-14 text-white"><span class="text-[9px] font-bold text-[#c8c1ff]" x-text="index===2?'LEADER':'MEMBER '+(index+1)"></span><b class="block truncate text-xs" x-text="slot.name"></b><span class="mt-1 block truncate text-[10px] text-white/70" x-text="slot.character.name"></span><span class="mt-2 inline-flex rounded bg-black/60 px-1.5 py-1 text-[9px] font-bold" x-text="'Lv.'+slot.level+' · 특훈 '+slot.training+' · 각성 '+slot.awakening"></span><span x-show="slot.snapshot" class="mt-1 block truncate text-[9px] text-pink-200" x-text="'스냅 · '+slot.snapshot?.name"></span></div></div></template>
                            <template x-if="!slot"><div class="grid h-full place-items-center text-center text-slate-400"><span><b class="block text-xl">＋</b><small class="text-[10px]" x-text="index===2?'리더 선택':'멤버 선택'"></small></span></div></template>
                        </button>
                    </template>
                </div>
                <div class="relative mt-4 rounded-lg border border-slate-200 bg-white p-4">
                    <button @click="recommendFormation()" :disabled="!chosenSong" class="absolute right-4 top-4 rounded bg-[#6c5ce7] px-3 py-2 text-[10px] font-black leading-tight text-white transition hover:bg-[#7d6ef0] disabled:opacity-40">추천 편성</button>
                    <div class="grid gap-4 sm:grid-cols-[96px_minmax(0,1fr)] sm:items-center">
                        <div class="aspect-square overflow-hidden rounded-md bg-slate-100"><template x-if="chosenSong"><img :src="chosenSong.image_url" class="h-full w-full object-cover" :alt="chosenSong.title"></template><template x-if="!chosenSong"><div class="grid h-full place-items-center text-2xl text-slate-500">♫</div></template></div>
                        <div class="min-w-0 pt-8 sm:pt-0"><p class="text-[10px] font-bold text-[#8b7cf6]">SCORE SIMULATOR · BETA</p><label class="mt-2 block text-xs text-slate-400">곡 선택<select x-model.number="songId" class="mt-2 w-full max-w-none border-slate-200 bg-slate-50 text-xs"><option :value="0">곡을 선택하세요</option><template x-for="song in songs" :key="song.id"><option :value="song.id" x-text="song.title+' · EX '+song.expert+' · '+number(song.note_count)+' notes'"></option></template></select></label><div x-show="chosenSong" class="mt-3 flex flex-wrap gap-x-4 gap-y-1 text-[10px] text-slate-400"><span>EX <b class="text-white" x-text="chosenSong?.expert"></b></span><span>노트 <b class="text-white" x-text="number(chosenSong?.note_count||0)"></b></span><span>BPM <b class="text-white" x-text="chosenSong?.bpm||'-'"></b></span></div></div>
                    </div>
                </div>
                <div class="mt-4 rounded-lg border border-slate-200 bg-white p-4">
                    <div class="flex gap-2"><input x-model="search" placeholder="멤버 검색" class="min-w-0 flex-1 rounded border-slate-200 bg-slate-50 px-3 py-2 text-xs"><select x-model="band" class="rounded border-slate-200 bg-slate-50 px-3 py-2 text-xs"><option value="">모든 밴드</option><template x-for="item in bands"><option x-text="item"></option></template></select></div>
                    <div class="mt-4 grid max-h-[560px] grid-cols-2 gap-2 overflow-y-auto pr-1 sm:grid-cols-3 md:grid-cols-4">
                        <template x-for="member in filtered" :key="member.id">
                            <button @click="prepare(member)" class="group overflow-hidden rounded border border-slate-200 bg-white text-left hover:border-[#6c5ce7]"><div class="aspect-[3/4] overflow-hidden bg-slate-100"><img :src="member.image_url" class="h-full w-full object-cover transition group-hover:scale-[1.02]"></div><div class="p-2"><b class="block truncate text-xs" x-text="member.name"></b><span class="block truncate text-[10px] text-slate-400" x-text="member.character.name"></span><div class="mt-1 text-[10px] font-bold text-[#8b7cf6]" x-text="number(power(member))"></div></div></button>
                        </template>
                    </div>
                    <p x-show="filtered.length===0" class="py-10 text-center text-xs text-slate-400">선택 가능한 카드가 없습니다.</p>
                </div>
            </div>
            <aside class="h-fit rounded-lg bg-[#24272f] p-6 text-white lg:sticky lg:top-28">
                <p class="text-[10px] font-bold text-[#a99eff]">FORMATION RESULT</p><div class="mt-5 flex items-end justify-between"><span class="text-xs text-slate-400">예상 종합력</span><b class="text-3xl tabular-nums" x-text="number(total)"></b></div>
                <div class="mt-6 rounded-lg border border-[#4a4e59] bg-[#1c1f26] p-4"><div class="flex items-center justify-between"><span class="text-[10px] font-bold text-pink-300">곡 기준 예상 점수</span><span class="rounded bg-pink-300/10 px-2 py-1 text-[9px] font-bold text-pink-300">BETA</span></div><div class="mt-4 text-center"><span class="text-[10px] text-slate-400">AP · 스킬 포함</span><b class="mt-1 block text-3xl tabular-nums" x-text="number(skillScore)"></b></div><div class="mt-4 grid grid-cols-2 divide-x border-t border-white/10 pt-3 text-center"><div><span class="text-[9px] text-slate-400">AP 기본</span><b class="mt-1 block text-sm" x-text="number(baseScore)"></b></div><div><span class="text-[9px] text-slate-400">스킬 상승</span><b class="mt-1 block text-sm text-emerald-400" x-text="'+'+number(Math.max(0,skillScore-baseScore))"></b></div></div><p class="mt-4 text-[9px] leading-4 text-slate-500">SPICA EXPERT 노트 수와 공개된 BanG Dream 계열 점수식을 사용한 예상값입니다. 실제 게임 결과와 차이가 날 수 있습니다.</p></div>
                <div class="mt-6 space-y-4">@foreach([['퍼포먼스','performance','#ef476f'],['테크닉','technique','#3b82f6'],['비주얼','visual','#8b5cf6']] as [$label,$key,$color])<div><div class="flex justify-between text-[10px]"><span class="text-slate-400">{{ $label }}</span><b x-text="number(sum('{{ $key }}'))"></b></div><div class="mt-2 h-1 rounded bg-white/10"><div class="h-full rounded" style="background:{{ $color }}" :style="'width:'+Math.min(100,sum('{{ $key }}')/850)+'%'"></div></div></div>@endforeach</div>
                <div class="mt-6 rounded bg-white/5 p-4"><div class="flex justify-between text-xs"><span>밴드 일치 보너스</span><b class="text-emerald-400" x-text="bonus+'%'"></b></div><div class="mt-3 flex justify-between border-t border-white/10 pt-3 text-xs"><span>리더 스킬 보너스</span><b class="text-pink-300" x-text="leaderBonus+'%'"></b></div><p class="mt-2 text-[10px] leading-5 text-slate-400">리더 슬롯의 리더 스킬과 전 멤버의 격주·스냅 서포트 스킬을 예상 점수에 반영합니다.</p></div>
                <button @click="reset()" class="mt-4 w-full rounded border border-white/15 py-2 text-xs font-bold">편성 초기화</button>
            </aside>
        </div>
        <div x-show="modal" x-cloak @keydown.escape.window="closeModal()" class="fixed inset-0 z-50 grid place-items-center bg-black/75 p-4 backdrop-blur-sm">
            <div @click.outside="closeModal()" class="flex max-h-[calc(100vh-2rem)] w-full max-w-[1320px] flex-col overflow-hidden rounded-xl border border-[#4a4e59] bg-[#20232b] text-white shadow-2xl">
                <div class="flex items-center justify-between border-b border-white/10 px-6 py-4"><div><p class="text-[10px] font-black text-[#a99eff]">MEMBER TRAINING</p><h2 class="mt-1 text-lg font-black">육성 상태 설정</h2></div><button @click="closeModal()" class="grid size-9 place-items-center rounded border border-white/15 text-lg">×</button></div>
                <template x-if="pending"><div class="grid min-h-0 flex-1 gap-6 overflow-y-auto p-6 md:grid-cols-[210px_minmax(0,1fr)] xl:grid-cols-[210px_minmax(0,1fr)_420px]">
                    <div><div class="relative aspect-[3/4] overflow-hidden rounded-lg border border-white/10"><img :src="pending.image_url" class="h-full w-full object-cover"><span class="absolute bottom-3 left-3 rounded bg-black/70 px-2 py-1 text-xs font-black" x-text="'Lv.'+setup.level"></span></div><b class="mt-3 block truncate" x-text="pending.name"></b><span class="mt-1 block text-xs text-slate-400" x-text="pending.character.name"></span></div>
                    <div class="space-y-5">
                        <div><div class="flex justify-between text-xs"><span class="text-slate-400">레벨</span><b><span x-text="setup.level"></span> / <span x-text="setupMaxLevel"></span></b></div><input type="range" min="1" :max="setupMaxLevel" x-model.number="setup.level" class="mt-3 w-full accent-[#8b7cf6]"><div class="mt-2 flex gap-2"><button @click="setup.level=1" class="rounded border border-white/15 px-3 py-2 text-xs">1</button><button @click="setup.level=baseMax(pending)" class="rounded border border-white/15 px-3 py-2 text-xs" x-text="baseMax(pending)"></button><button @click="setup.level=setupMaxLevel" class="rounded border border-white/15 px-3 py-2 text-xs">MAX</button></div></div>
                        <div><div class="flex items-center justify-between"><span class="text-xs text-slate-400">특훈</span><span class="text-[10px] text-slate-500">레벨 상한을 단계마다 10씩 개방</span></div><div class="mt-2 flex gap-2"><template x-for="training in [0,1,2,3,4]"><button @click="setTraining(training)" class="grid size-10 place-items-center rounded border text-xs font-black" :class="setup.training===training?'border-[#8b7cf6] bg-[#6c5ce7]':'border-white/15'" x-text="training"></button></template></div></div>
                        <div><div class="flex items-center justify-between"><span class="text-xs text-slate-400">각성</span><span class="text-[10px] text-slate-500">리더 스킬 Lv.<span x-text="setup.awakening + 1"></span></span></div><div class="mt-2 flex gap-2"><template x-for="awakening in [0,1,2,3,4]"><button @click="setup.awakening=awakening" class="grid size-10 place-items-center rounded border text-xs font-black" :class="setup.awakening===awakening?'border-pink-300 bg-pink-300 text-slate-950':'border-white/15'" x-text="awakening"></button></template></div></div>
                        <div><span class="text-xs text-slate-400">스킬 레벨</span><div class="mt-2 flex gap-2"><template x-for="level in [1,2,3,4,5]"><button @click="setup.skillLevel=level" class="grid size-10 place-items-center rounded border text-xs font-black" :class="setup.skillLevel===level?'border-[#8b7cf6] bg-[#6c5ce7]':'border-white/15'" x-text="level"></button></template></div></div>
                        <div class="grid grid-cols-4 divide-x divide-white/10 rounded-lg border border-white/10 bg-black/15 text-center"><div class="p-3"><span class="text-[9px] text-slate-400">종합력</span><b class="mt-1 block text-base" x-text="number(pendingTotal)"></b></div><template x-for="item in [['P','performance'],['T','technique'],['V','visual']]" :key="item[1]"><div class="p-3"><span class="text-[9px] text-slate-400" x-text="item[0]"></span><b class="mt-1 block text-sm" x-text="number(pendingStat(item[1]))"></b></div></template></div>
                        <div class="rounded-lg border border-white/10 p-4"><div class="flex justify-between"><span class="text-[10px] font-bold text-slate-400">LIVE SKILL · Lv.<span x-text="setup.skillLevel"></span></span><b class="text-sm text-emerald-400" x-text="'스코어 +'+pendingScoreUp+'%'"></b></div><div class="spica-skill mt-2 text-xs leading-5 text-slate-300" x-html="selectedSkill(pending,setup.skillLevel)"></div><div class="mt-3 border-t border-white/10 pt-3"><span class="text-[10px] font-bold text-slate-400" x-text="active===2?'LEADER Lv.'+(setup.awakening+1)+' + GEKISOU SKILL':'GEKISOU SKILL'"></span><div x-show="active===2" class="spica-skill mt-2 text-xs leading-5 text-slate-300" x-html="selectedLeaderSkill(pending,setup.awakening+1)"></div><div class="spica-skill mt-2 text-xs leading-5 text-slate-300" x-html="selectedGekisouSkill(pending,setup.skillLevel)"></div></div></div>
                    </div>
                    <div class="flex min-h-[540px] flex-col rounded-lg border border-white/10 bg-black/10 p-4 md:col-span-2 xl:col-span-1 xl:min-h-0"><div class="flex shrink-0 items-center justify-between"><div><span class="text-xs font-black">캐릭터 스냅</span><p class="mt-1 text-[10px] text-slate-400">스냅을 선택하고 별도 육성 상태를 설정합니다.</p></div><button x-show="setup.snapshotId" @click="clearSnapshot()" class="text-[10px] text-slate-400">선택 해제</button></div><div class="mt-4 grid min-h-0 grid-cols-2 content-start gap-2 overflow-y-auto pr-1" :class="pendingSnapshot?'max-h-52 shrink-0':'flex-1'"><template x-for="snap in availableSnapshots" :key="snap.id"><button @click="chooseSnapshot(snap)" class="overflow-hidden rounded border text-left" :class="setup.snapshotId===snap.id?'border-pink-300 ring-2 ring-pink-300/20':'border-white/10'"><img :src="snap.image_url" class="aspect-[4/3] w-full object-cover"><span class="block truncate p-2 text-[10px] font-bold" x-text="snap.name"></span></button></template><p x-show="availableSnapshots.length===0" class="col-span-2 py-4 text-xs text-slate-500">선택 가능한 스냅이 없습니다.</p></div>
                        <template x-if="pendingSnapshot"><div class="rounded-lg border border-pink-300/20 bg-pink-300/5 p-4"><div class="flex items-center gap-3"><img :src="pendingSnapshot.image_url" class="h-16 w-20 rounded object-cover"><div class="min-w-0"><b class="block truncate text-sm" x-text="pendingSnapshot.name"></b><span class="text-[10px] text-slate-400">스냅 종합력 <b class="text-pink-200" x-text="number(pendingSnapshotTotal)"></b></span></div></div><div class="mt-4 grid gap-4 sm:grid-cols-2"><div><div class="flex justify-between text-[10px]"><span>스냅 레벨</span><b x-text="setup.snapshotLevel+' / '+snapshotMaxLevel"></b></div><input type="range" min="1" :max="snapshotMaxLevel" x-model.number="setup.snapshotLevel" class="mt-2 w-full accent-pink-300"></div><div><span class="text-[10px]">스냅 각성</span><div class="mt-2 flex gap-1"><template x-for="rank in [0,1,2,3,4]"><button @click="setSnapshotRank(rank)" class="grid size-8 place-items-center rounded border text-[10px]" :class="setup.snapshotRank===rank?'bg-pink-300 text-slate-950':'border-white/15'" x-text="rank"></button></template></div></div></div><div class="mt-4"><span class="text-[10px]">서포트 스킬 레벨</span><div class="mt-2 flex gap-1"><template x-for="level in [1,2,3,4,5]"><button @click="setup.snapshotSkillLevel=level" class="grid size-8 place-items-center rounded border text-[10px]" :class="setup.snapshotSkillLevel===level?'bg-[#6c5ce7]':'border-white/15'" x-text="level"></button></template></div></div></div></template>
                    </div>
                </div></template>
                <div class="flex justify-end gap-2 border-t border-white/10 px-6 py-4"><button @click="closeModal()" class="rounded border border-white/15 px-5 py-2.5 text-xs font-bold">취소</button><button @click="confirmMember()" class="rounded bg-[#6c5ce7] px-5 py-2.5 text-xs font-black">편성에 넣기</button></div>
            </div>
        </div>
    </section>
    <script>
        function formation(members,songs){return{members,songs,slots:[null,null,null,null,null],active:0,search:'',band:'',songId:0,modal:false,pending:null,setup:{level:1,rank:0,skillLevel:1},rates:{2:{1:.4086,30:.6571,40:.7429,50:.8286,70:1},3:{1:.4075,30:.625,40:.7,50:.775,70:.925,80:1},4:{1:.4067,30:.6,40:.6667,50:.7333,70:.8667,80:.9333,90:1}},get chosenSong(){return this.songs.find(s=>s.id===this.songId)||null},get bands(){return[...new Set(this.members.map(m=>m.character.band))]},get selectedCharacterIds(){return this.slots.map((m,i)=>i===this.active?null:m?.character_id).filter(Boolean)},get filtered(){return this.members.filter(m=>!this.selectedCharacterIds.includes(m.character_id)&&(!this.band||m.character.band===this.band)&&(!this.search||(m.name+m.character.name).includes(this.search)))},baseMax(m){return({2:30,3:40,4:50})[m.rarity_id]||50},get setupMaxLevel(){return Math.min((({2:70,3:80,4:90})[this.pending?.rarity_id]||90),this.baseMax(this.pending)+this.setup.rank*10)},growthRate(m,level){let points=Object.entries(this.rates[m.rarity_id]||this.rates[4]).map(([l,r])=>[+l,+r]).sort((a,b)=>a[0]-b[0]),exact=points.find(p=>p[0]===level);if(exact)return exact[1];let lower=points[0],upper=points.at(-1);for(let i=1;i<points.length;i++)if(level<points[i][0]){lower=points[i-1];upper=points[i];break}return lower[1]+(upper[1]-lower[1])*(level-lower[0])/(upper[0]-lower[0])},configuredStat(m,k,level,rank){let maximum=+m['max_'+k]||0;return maximum?Math.round(maximum*this.growthRate(m,level)*(1+rank*.025)):+m[k]},pendingStat(k){return this.pending?this.configuredStat(this.pending,k,this.setup.level,this.setup.rank):0},get pendingTotal(){return this.pendingStat('performance')+this.pendingStat('technique')+this.pendingStat('visual')},power(m){return m.display_power},prepare(m){if(this.selectedCharacterIds.includes(m.character_id))return;this.pending=m;this.setup={level:this.baseMax(m),rank:0,skillLevel:1};this.modal=true},openSlot(index){this.active=index;if(this.slots[index]){let m=this.slots[index];this.pending=m;this.setup={level:m.level,rank:m.rank,skillLevel:m.skillLevel};this.modal=true}},closeModal(){this.modal=false;this.pending=null},setRank(rank){this.setup.rank=rank;this.setup.level=Math.min(this.setup.level,this.setupMaxLevel)},selectedSkill(m,level){return m?.live_skill_levels?.[level]||m?.live_skill_levels?.[String(level)]||m?.live_skill||'해당 스킬 없음'},scorePercent(m,level){let text=this.selectedSkill(m,level).replace(/<[^>]*>/g,' '),values=[...text.matchAll(/([0-9]+(?:\.[0-9]+)?)\s*%/g)].map(x=>+x[1]);return values.length?Math.max(...values):(+m.score_up||0)},get pendingScoreUp(){return this.pending?this.scorePercent(this.pending,this.setup.skillLevel):0},confirmMember(){if(!this.pending||this.selectedCharacterIds.includes(this.pending.character_id))return;let m={...this.pending,level:this.setup.level,rank:this.setup.rank,skillLevel:this.setup.skillLevel,display_performance:this.pendingStat('performance'),display_technique:this.pendingStat('technique'),display_visual:this.pendingStat('visual'),display_power:this.pendingTotal,selected_live_skill:this.selectedSkill(this.pending,this.setup.skillLevel),selected_score_up:this.pendingScoreUp};this.slots[this.active]=m;this.slots=[...this.slots];this.closeModal();let n=this.slots.findIndex(x=>!x);if(n>=0)this.active=n},reset(){this.slots=[null,null,null,null,null];this.active=0;this.closeModal()},sum(k){return this.slots.filter(Boolean).reduce((a,m)=>a+m['display_'+k],0)},get bonus(){let c={};this.slots.filter(Boolean).forEach(m=>c[m.character.band]=(c[m.character.band]||0)+1);let n=Math.max(0,...Object.values(c));return n===5?15:n>=3?5:0},get total(){let raw=this.sum('performance')+this.sum('technique')+this.sum('visual');return Math.round(raw*(1+this.bonus/100))},comboRate(i){return i<=20?1:i<=50?1.01:i<=100?1.02:i<=150?1.03:i<=200?1.04:i<=250?1.05:i<=300?1.06:i<=400?1.07:i<=500?1.08:i<=600?1.09:i<=700?1.10:1.11},get baseScore(){let s=this.chosenSong,n=s?.note_count||0;if(!s||!n||!this.total)return 0;let per=this.total*3*(1+(s.expert-5)*.01)/n,score=0;for(let i=1;i<=n;i++)score+=Math.floor(per*1.1*this.comboRate(i));return score},skillDuration(m){let hit=(m.selected_live_skill||m.live_skill||'').replace(/<[^>]*>/g,'').match(/([0-9]+(?:\.[0-9]+)?)초간/);return +(hit?.[1]||5)},get estimatedSongDuration(){let s=this.chosenSong;if(!s)return 120;let bpm=+(String(s.bpm||'160').match(/[0-9]+(?:\.[0-9]+)?/)?.[0]||160);return Math.max(90,Math.min(180,s.note_count/(bpm*1.5)*60))},get skillScore(){if(!this.baseScore)return 0;let active=this.slots.filter(Boolean),boost=active.reduce((sum,m)=>sum+(m.selected_score_up/100)*(this.skillDuration(m)/this.estimatedSongDuration)*(this.slots.indexOf(m)===2?2:1),0);return Math.round(this.baseScore*(1+boost))},number(n){return new Intl.NumberFormat('ko-KR').format(Math.round(n||0))}}}
    </script>
    @include('partials.formation-script')
</x-layouts.wiki>
